source.exploreUrl:
@js:
const currentUrl = getCurrentUrl();
const topListRoute = 'top/list';

const combineUrl = (cateIndex, dataIndex) => {
    if (cateIndex == 0 && dataIndex == 0) {
        return ``;
    } else {
        const cateId = cateIndex == 7 ? 8 : cateIndex;
        return `${currentUrl}${topListRoute}/${cateId}/${dataIndex}/{{page}}.html`;
    }
};

const combineLable = (cateLable, dataLable) => {
    if (cateLable == "不选择" && dataLable == "不选择") {
        return "请至少选择一项";
    } else {
        let lable = cateLable + "·" + dataLable;
        return lable.replace(/·?不选择·?/g, "");
    }
}

let currentCateIndex = String(source.get("cateRankIndex")) || 0;
let currentDataIndex = String(source.get("dataRankIndex")) || 1;
const currentCateLabel = ranks.category[currentCateIndex];
const currentDataLabel = ranks.data[currentDataIndex];
const fullLabel = combineLable(currentCateLabel, currentDataLabel)
const fullUrl = combineUrl(currentCateIndex, currentDataIndex);

let ui = [{
        title: '分类榜',
        type: 'select',
        action: 'onSelectorChanged(String(infoMap["分类榜"]),"category")',
        chars: ranks.category,
        default: ranks.category[currentCateIndex],
        style: {
            "layout_flexGrow": 0,
            "layout_flexShrink": 1,
            "layout_alignSelf": "auto",
            "layout_flexBasisPercent": 0.45,
            "layout_wrapBefore": false
        }
    },
    {
        title: '数据榜',
        type: 'select',
        action: 'onSelectorChanged(String(infoMap["数据榜"]),"data")',
        chars: ranks.data,
        default: ranks.data[currentDataIndex],
        style: {
            "layout_flexGrow": 0,
            "layout_flexShrink": 1,
            "layout_alignSelf": "auto",
            "layout_flexBasisPercent": 0.45,
            "layout_wrapBefore": false
        }
    },
    {
        title: fullLabel,
        url: fullUrl,
        style: {
            "layout_flexGrow": 0,
            "layout_flexShrink": 1,
            "layout_alignSelf": "auto",
            "layout_flexBasisPercent": 1,
            "layout_wrapBefore": false
        }
    }
];
JSON.stringify(ui);

