source.jsLib:
const bookSites = {
    '主域名': 'https://www.pilishuwu.com/',
    '镜像线路1': 'https://www.pilibook.net/',
    '镜像线路2': 'https://www.pili45.com/'
};

const ranks = {
    data: [
        '不选择', '最新入库', '全部点击', '本年点击', '本月点击', '本周点击', '本日点击',
        '全部收藏', '本年收藏', '本月收藏', '本周收藏', '本日收藏',
        '全部推荐', '本年推荐', '本月推荐', '本周推荐', '本日推荐',
        '评论数量', '点赞数量', '讨厌数量', '评分分数', '全本字数', '章节数量'
    ],
    category: [
        '不选择',
        '男频小说', '女频小说', '电子图书', '无cp小说',
        '纯爱小说', '百合小说', '轻小说'
    ]
};

const urlToName = Object.fromEntries(
    Object.entries(bookSites).map(([name, url]) => [url, name])
);

function getUrlByName(name) {
    return bookSites[name] || null;
}

function getNameByUrl(url) {
    return urlToName[url] || null;
}

function getCurrentUrl() {
    const { source } = this;
    return String(source.get("url")) || bookSites['镜像线路1'];
}

function onSelectorChanged(selectedLabel, type) {
    const { source, java } = this;

    const list = type === "data" ? ranks.data : ranks.category;
    const saveKey = type === "data" ? "dataRankIndex" : "cateRankIndex";
    const selectedIndex = list.indexOf(selectedLabel);
    source.put(saveKey, selectedIndex);

    java.refreshExplore();
}

