const siteNames = Object.keys(bookSites);
const currentUrl = getCurrentUrl();
const currentSiteName = getNameByUrl(String(currentUrl));

const mainUI = [{
        name: '当前站点',
        type: 'select',
        chars: siteNames,
        action: 'setCurrentUrl()',
        default: currentSiteName,
        style: {
            layout_flexBasisPercent: 1
        }
    },
    {
        name: '网站',
        type: 'button',
        action: 'toSite()',
        style: {
            layout_flexBasisPercent: 0.45
        }
    },
    {
        name: '公告',
        type: 'button',
        action: 'toNotice()',
        style: {
            layout_flexBasisPercent: 0.45
        }
    }
];

JSON.stringify(mainUI);

