function login() {}

function setCurrentUrl() {
    let currentSiteName = result.get("当前站点");
    const targetUrl = bookSites[currentSiteName];
    source.put("url", targetUrl);
}

function toSite() {
    const currentUrl = getCurrentUrl();
    java.startBrowser(currentUrl,"霹雳书屋");
}

function toNotice() {
  java.startBrowser("https://www.pilixiaoshuo.com/", "公告");
}

