var QM_KEY = 'd3dGiJc651gSQ8w1';
var QM_AES = '242ccb8230d709e1';
var QM_BC = 'https://api-bc.wtzw.com';
var QM_KS = 'https://api-ks.wtzw.com';

function qmMd5(s) {
    var b = Packages.java.security.MessageDigest.getInstance('MD5')
        .digest(new Packages.java.lang.String(s).getBytes('UTF-8'));
    var h = '';
    for (var i = 0; i < b.length; i++) {
        var x = (b[i] & 0xff).toString(16);
        h += (x.length < 2 ? '0' : '') + x;
    }
    return h;
}

function qmSign(o) {
    return qmMd5(Object.keys(o).sort().map(function (k) { return k + '=' + o[k]; }).join('') + QM_KEY);
}

var QM_HEADERS = (function () {
    var h = {'app-version': '80400', 'platform': 'android', 'reg': '0', 'AUTHORIZATION': '',
             'application-id': 'com.****.reader', 'net-env': '1', 'channel': 'unknown', 'qm-params': ''};
    h.sign = qmSign(h);
    return JSON.stringify({headers: h});
