function qmaNovelExplore(infoMap,source){return (function(){
var CHANNELS = ['男频', '女频', '出版'];
var OVER = [['全部状态', '-99'], ['完结', '1'], ['连载', '0']];
var WORDS = [['全部字数', '-99'], ['50万以下', '1'], ['50-100万', '2'], ['100-300万', '3'], ['300万以上', '4']];
var SORT = [['按热度', '0'], ['按更新', '1'], ['按评分', '2'], ['按新书', '3']];
var STYLE = {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true};

var state = qmSaveExploreState(
    typeof infoMap === 'undefined' ? null : infoMap,
    typeof source === 'undefined' ? null : source
);
var action = "(function(){var currentInfo=typeof infoMap==='undefined'?null:infoMap;var currentSource=typeof source==='undefined'?null:source;qmSaveExploreState(currentInfo,currentSource);try{java.reUiView(false);}catch(e){try{java.refreshExplore();}catch(e2){}}})()";
var encoded = encodeURIComponent(JSON.stringify(state));

function labels(options) {
    return options.map(function (option) { return option[0]; });
}
function selectedLabel(options, value) {
    for (var i = 0; i < options.length; i++) {
        if (String(options[i][1]) == String(value)) return options[i][0];
    }
    return options[0][0];
}

var resultName = '查看筛选结果 · ' + state.channel + ' · ' + state.group + ' · ' + state.tag;
var resultUrl = '<js>qmBuildExploreUrlFromEncoded(java,' + JSON.stringify(encoded) + ',typeof page=="undefined"?1:page)</js>';
return JSON.stringify([
    {title: '频道', type: 'select', chars: CHANNELS, default: state.channel, action: action, style: STYLE},
    {title: '分类分组', type: 'select', chars: qmExploreGroupNames(state.channel), default: state.group, action: action, style: STYLE},
    {title: '分类标签', type: 'select', chars: qmExploreTagNames(state.channel, state.group), default: state.tag, action: action, style: STYLE},
    {title: '状态', type: 'select', chars: labels(OVER), default: selectedLabel(OVER, state.over), action: action, style: STYLE},
    {title: '字数', type: 'select', chars: labels(WORDS), default: selectedLabel(WORDS, state.words), action: action, style: STYLE},
    {title: '排序', type: 'select', chars: labels(SORT), default: selectedLabel(SORT, state.sort), action: action, style: STYLE},
    {title: resultName, type: 'url', url: resultUrl, style: STYLE}
]);
})()
;}
var QMA_ORIGINAL_LOGIN = [{"name": "开启段评（刷新正文后生效）", "type": "button", "action": "qmpcSetEnabled.call(this,true)"}, {"name": "关闭段评（刷新正文后生效）", "type": "button", "action": "qmpcSetEnabled.call(this,false)"}, {"name": "查看最近段评加载状态", "type": "button", "action": "qmpcShowStatus.call(this)"}];
/* Independent discovery states; catalogs are snapshots of verified official metadata. */
var QMA_DISC = (function(){
  var MODES=[['小说','novel'],['听书','audio'],['漫剧','animated'],['短剧','drama']];
  var OVER=[['全部','-99'],['完结','1'],['连载','0']];
  var SORT=[['最高热度','1'],['最近更新','2'],['最新上架','3']];
  var KEYS={category:'听书分类',tag:'听书标签',over:'听书状态',sort:'听书排序'};
  var STYLE={layout_flexGrow:1,layout_flexBasisPercent:1,layout_wrapBefore:true};
  function src(ctx){return QMA_NET.source(ctx);}
  function j(ctx){return QMA_NET.java(ctx);}
  function get(map,key){return qmExploreMapGet(map,key);}
  function put(map,key,value){qmExploreMapPut(map,key,value);}
  function stored(ctx,key){try{return JSON.parse(String(src(ctx).get(key)||'{}'));}catch(e){return {};}}
  function option(options,value,fallback){
    for(var i=0;i<options.length;i++)if(String(value)===options[i][0]||String(value)===options[i][1])return String(options[i][1]);
    return String(fallback);
  }
  function label(options,value){for(var i=0;i<options.length;i++)if(String(options[i][1])===String(value))return options[i][0];return options[0][0];}
  function mode(){return option(MODES,src(this).get('qma_explore_mode'),'novel');}
  function loginUi(){
    var rows=[{name:'发现内容类型',type:'select',chars:MODES.map(function(x){return x[0];}),default:label(MODES,mode.call(this)),
      action:'QMA_DISC.setMode.call(this,result)',style:STYLE}];
    rows=rows.concat(QMA_ORIGINAL_LOGIN);
    rows.push({name:'聚合使用说明',type:'button',action:'QMA.help.call(this)'},
      {name:'查看媒体接口状态',type:'button',action:'QMA.status.call(this)'},
      {name:'测试媒体游客登录',type:'button',action:'QMA.login.call(this)'},
      {name:'重置媒体游客身份',type:'button',action:'QMA.reset.call(this)'});
    return JSON.stringify(rows);
  }
  function setMode(values){
    var selected=typeof values==='string'?values:get(values,'发现内容类型');
    var chosen=option(MODES,selected,'');
    if(!chosen)throw new Error('请选择小说、听书、漫剧或短剧');
    var s=src(this), previous=mode.call(this);
    s.put('qma_explore_mode',chosen);
    // Merge only our key; preserve other saved login settings.
    try {
      var saved=JSON.parse(String(s.getLoginInfo()||'{}'));
      saved['发现内容类型']=label(MODES,chosen);
      s.putLoginInfo(JSON.stringify(saved));
    }catch(ignored){}
    var cleared=false;
    if(previous!==chosen){try{s.refreshExplore();cleared=true;}catch(ignored2){}}
    j(this).longToast('发现已切换为'+label(MODES,chosen)+(cleared?'，缓存已清除':'')+'。返回发现后收起再展开书源；如仍显示旧布局，请长按书源→刷新。');
  }
  function audioCategory(value){
    for(var i=0;i<QMA_CATALOG.audio.length;i++){
      var c=QMA_CATALOG.audio[i];if(String(value)===c.name||String(value)===c.id)return c;
    }
    return QMA_CATALOG.audio[0];
  }
  function audioNormalize(value){
    value=value||{};var c=audioCategory(value.category);
    return {category:c.id,tag:option(c.tags,value.tag,'-99'),over:option(OVER,value.over,'-99'),sort:option(SORT,value.sort,'1')};
  }
  function audioState(ctx,info){
    var old=audioNormalize(stored(ctx,'qma_audio_filters'));
    var category=audioCategory(get(info,KEYS.category)||old.category);
    var tag=category.id!==old.category?'-99':get(info,KEYS.tag)||old.tag;
    var value=audioNormalize({category:category.id,tag:tag,over:get(info,KEYS.over)||old.over,sort:get(info,KEYS.sort)||old.sort});
    Object.keys(KEYS).forEach(function(k){
      var display=k==='category'?category.name:k==='tag'?label(category.tags,value.tag):label(k==='over'?OVER:SORT,value[k]);
      put(info,KEYS[k],display);
    });
    try{if(info&&info.saveNow)info.saveNow();}catch(ignored){}
    src(ctx).put('qma_audio_filters',JSON.stringify(value));
    return value;
  }
  function audioChanged(info){
    audioState(this,info);
    try{src(this).refreshExplore();}catch(ignored){}
    // From an ExploreKind action this callback rebuilds discovery, not login.
    try{j(this).refreshExplore();}catch(ignored2){}
  }
  function explore(info){
    var selected=mode.call(this);
    if(selected==='novel')return qmaNovelExplore.call(this,info,src(this));
    if(selected!=='audio'){
      return JSON.stringify(QMA_CATALOG[selected].map(function(t){
        return {title:t[0],type:'url',url:'@js:QMA.exploreUrl.call(this,'+JSON.stringify(selected)+',page,'+JSON.stringify(t[1])+')',
          style:{layout_flexBasisPercent:t[0].length>4?0.5:0.25,layout_flexGrow:1}};
      }));
    }
    var value=audioState(this,info),category=audioCategory(value.category);
    var action='QMA_DISC.audioChanged.call(this,typeof infoMap==="undefined"?null:infoMap)';
    var values=[QMA_CATALOG.audio.map(function(c){return c.name;}),category.tags.map(function(t){return t[0];}),OVER.map(function(t){return t[0];}),SORT.map(function(t){return t[0];})];
    var defaults=[category.name,label(category.tags,value.tag),label(OVER,value.over),label(SORT,value.sort)];
    var keys=[KEYS.category,KEYS.tag,KEYS.over,KEYS.sort],names=['分类','标签','状态','排序'];
    // beta.45 ExploreKind.equals ignores chars. Change the tag row's action too,
    // so Compose receives new options even when both defaults are still 全部.
    var rows=keys.map(function(k,index){return {title:k,viewName:JSON.stringify(names[index]),type:'select',chars:values[index],default:defaults[index],
      action:action+(index===1?'; /* category '+category.id+' */':''),style:STYLE};});
    var name='查看筛选结果 · '+defaults.join(' · ');
    rows.push({title:name,type:'url',url:'@js:QMA.exploreUrl.call(this,"audio",page,'+JSON.stringify(value)+')',style:STYLE});
    return JSON.stringify(rows);
  }
  function audioParams(value,page){
    value=audioNormalize(value);
    var p={category_id:value.category,category_type:'2',page:String(page),need_filters:'1',need_category:'1',over:value.over,sort:value.sort};
    if(value.tag!=='-99')p.tag_ids=value.tag;
    return p;
  }
  function mem(ctx,key,value){
    var c=QMA_NET.cache(ctx);
    try{if(value!==undefined){if(c)c.putMemory(key,JSON.stringify(value));return value;}return JSON.parse(String(c&&c.getFromMemory(key)||'{}'));}catch(e){return {};}
  }
  function audioKey(value){return 'qma-audio-pages-'+qmMd5(JSON.stringify(audioNormalize(value)));}
  function audioEnded(ctx,value,page){if(page===1)mem(ctx,audioKey(value),{});return Number(mem(ctx,audioKey(value)).total)>0&&page>Number(mem(ctx,audioKey(value)).total);}
  function audioPages(ctx,value,metadata){if(metadata&&/^\d+$/.test(String(metadata.total_pages)))mem(ctx,audioKey(value),{total:Number(metadata.total_pages)});}
  function videoTag(selected,tag){
    var tags=QMA_CATALOG[selected]||[];
    for(var i=0;i<tags.length;i++)if(String(tag)===tags[i][1])return String(tag);
    throw new Error('视频分类已失效，请刷新发现页');
  }
  function videoKey(m){return 'qma-video-pages-'+m.mode+'-'+videoTag(m.mode,m.tag||'0');}
  function videoParams(ctx,m){
    var key=videoKey(m),state=m.page===1?{pages:{}}:mem(ctx,key);
    if(m.page===1)mem(ctx,key,state);
    if(state.end&&m.page>state.end)return null;
    var ids=[],seen={};
    Object.keys(state.pages||{}).sort(function(a,b){return Number(a)-Number(b);}).forEach(function(p){if(Number(p)<m.page)ids=ids.concat(state.pages[p]);});
    ids=ids.filter(function(x){if(seen[x])return false;seen[x]=1;return true;}).slice(-120);
    var upload=ids.map(function(x){return {id:x,item_type:m.mode==='animated'?'14':'11',ts:String(Date.now()),type:'0'};});
    var p={page:String(m.page),playlet_privacy:'1',read_preference:'0',refresh_state:m.page===1?'4':'7',tag_id:m.tag||'0',upload_ids:JSON.stringify(upload)};
    if(m.mode==='animated')p.change_tag=m.page===1?'1':'0';
    return p;
  }
  function videoRows(ctx,m,rows,next){
    var key=videoKey(m),state=mem(ctx,key),prior={},local={};state.pages=state.pages||{};
    Object.keys(state.pages).forEach(function(p){if(Number(p)<m.page)state.pages[p].forEach(function(x){prior[x]=true;});});
    var filtered=rows.filter(function(x){var i=String(x.playlet_id||x.id||'');if(!i||prior[i]||local[i])return false;local[i]=true;return true;});
    state.pages[String(m.page)]=Object.keys(local);
    if(!rows.length||next!=null&&(String(next)===''||Number(next)<=m.page))state.end=m.page;
    Object.keys(state.pages).forEach(function(p){if(Number(p)<m.page-8)delete state.pages[p];});
    mem(ctx,key,state);return filtered;
  }
  return {mode:mode,loginUi:loginUi,setMode:setMode,explore:explore,audioNormalize:audioNormalize,audioChanged:audioChanged,
    audioParams:audioParams,audioEnded:audioEnded,audioPages:audioPages,videoTag:videoTag,videoParams:videoParams,videoRows:videoRows};
})();

ruleBookInfo.init:
@js:
(function(){
if (QMA.meta.call(this,baseUrl,result)) return JSON.stringify(QMA.info.call(this,baseUrl,result));
return (function(){
return (function () {
    var raw = String(result == null ? '' : result);
    var payload;
    try {
        payload = JSON.parse(raw);
    } catch (e) {
        throw new Error('七猫详情接口未返回有效 JSON，请查看调试响应');
    }
    function isBook(value) {
        return value && typeof value === 'object' && !Array.isArray(value)
            && value.id != null && String(value.id) !== ''
            && typeof value.title === 'string' && value.title.replace(/\s/g, '') !== ''
            && !('books' in value) && !('filters' in value);
    }
    function isFlatBook(value) {
        return isBook(value) && ('author' in value || 'words_num' in value || 'image_link' in value);
    }
    if (payload && payload.data && isBook(payload.data.book)) {
        return JSON.stringify(payload.data.book);
    }
    if (payload && isFlatBook(payload.data)) {
        return JSON.stringify(payload.data);
    }
    if (isFlatBook(payload)) return JSON.stringify(payload);
